mapper.select:
select w.withdraw_id, w.member_id, m.phone, m.real_name, w.currency, w.wallet_type_code, t.type_name as wallet_type_name,
       w.amount, w.fee_amount, w.arrival_amount, w.account_info, w.pay_method, w.status,
       w.audit_by, w.audit_time, w.audit_remark, w.pay_proof_url, w.create_time, w.remark
from biz_withdraw w
left join biz_member m on m.member_id = w.member_id
left join biz_wallet_type t on t.type_code = w.wallet_type_code

    and w.withdraw_id = #{withdrawId}
    and w.member_id = #{memberId}
    and w.currency = #{currency}
    and w.status = #{status}
    and w.wallet_type_code = #{walletTypeCode}
    and m.phone like concat('%', #{phone}, '%')
    and w.create_time >= #{params.beginTime}
    and w.create_time < date_add(#{params.endTime}, interval 1 day)

order by w.withdraw_id desc

mapper.update:
update biz_withdraw
status = #{status}, audit_by = #{auditBy}, audit_time = #{auditTime}, audit_remark = #{auditRemark}, pay_proof_url = #{payProofUrl},
where withdraw_id = #{withdrawId}
